import {bankItems,bankStimuli,BANK_VERSION} from './platform-bank.js';
import {SESSION_KEY,FORM_COUNT,DOMAINS,LEVELS,createSession,loadSession,answerQuestion,completeBlock,summarizeSession,exportSession} from './platform-engine.js';
import {analyzePilot} from './platform-validation.js';
import {skillLabels,labelFor,practiceFor,writingTasks,weekPlan} from './platform-copy.js';
import {escapeHTML as esc} from './benchmark-engine.js';
import {listeningPlayerHTML,mountListeningPlayer,listeningAnswerAvailable,clearListeningPositions} from './listening-player.js';

export const PLATFORM_ROUTES=new Set(['assessment-setup','assessment','my-report','writing','teacher-review','pilot-lab','bank']);
const byId=new Map(bankItems.map(q=>[q.id,q])),sources=new Map(bankStimuli.map(s=>[s.id,s]));
let storageOK=true;
const read=key=>{try{return localStorage.getItem(key);}catch{storageOK=false;return null;}};
let savedRaw=read(SESSION_KEY);
let session=loadSession(savedRaw,bankItems,BANK_VERSION),lang='ru',page=0,domainFilter='all',levelFilter='all',search='',writingTrack='independent',teacherAttempt=null,teacherDraft=null,pilotEntries=[],pilotResult=null;
let currentNotice=()=>{};
const RECOVERY_KEY=SESSION_KEY+':tab-recovery';
let writeConflict=false,pendingSaves=0,saveQueue=Promise.resolve(),guardRefresh=()=>{},recoveryRaw=null;
try{recoveryRaw=sessionStorage.getItem(RECOVERY_KEY);}catch{}
export function platformSummary(){return {bankCount:bankItems.length,hasAttempt:!!session,finished:session?.finished===true};}
const t=(ru,en)=>lang==='ru'?ru:en;
const local=value=>typeof value==='object'&&value?value[lang]??value.en??'':value??'';
const domainLabel=domain=>({language:t('Языковые средства','Language use'),reading:t('Чтение','Reading'),listening:t('Аудирование','Listening'),writing:t('Письмо','Writing'),speaking:t('Говорение','Speaking')})[domain]||domain;
const button=(label,action,primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':''}" data-p-action="${action}" ${extra}>${esc(label)}</button>`;
const link=(label,hash,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${hash}">${esc(label)}</a>`;
const conflictWarning=()=>writeConflict?`<div class="notice platform-conflict-warning" role="alert"><strong>${t('Другая вкладка изменила сохранённое прохождение.','Another tab changed the saved attempt.')}</strong><p>${t('Эта вкладка приостановлена, чтобы не затереть ответы. Её версия не объединяется с другой автоматически. Сначала сохраните копию, затем загрузите последнюю сохранённую версию.','This tab is paused to protect your responses. Its version is not merged automatically. Save a copy, then load the latest saved version.')}</p><div class="actions">${button(t('Скачать версию этой вкладки','Download this tab’s copy'),'conflict-backup')}${button(t('Скачать копию и загрузить сохранённое','Download copy and load saved progress'),'conflict-reload',true)}</div></div>`:recoveryRaw?`<div class="notice platform-conflict-warning"><p>${t('Сохранена отдельная резервная версия из этой вкладки. Она не заменяла текущее прохождение; её можно скачать и позднее импортировать.','A separate recovery version from this tab is available. It has not replaced the current attempt; download it to import later.')}</p><div class="actions">${button(t('Скачать резервную версию','Download recovery copy'),'conflict-backup')}${button(t('Убрать резервную копию вкладки','Dismiss tab recovery copy'),'conflict-dismiss')}</div></div>`:'';
const storageWarning=()=>`${!storageOK?`<div class="notice platform-storage-warning">${t('Безопасное сохранение в браузере недоступно. Скачайте ответы перед закрытием вкладки.','Safe browser saving is unavailable. Download your responses before closing this tab.')}</div>`:''}${conflictWarning()}`;
const shell=(title,subtitle,body)=>`<main id="main" class="wrap page platform-page"><div class="page-intro"><div class="eyebrow">${t('Английский в деталях','English in detail')}</div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${storageWarning()}${body}</main>`;
const warning=()=>`<div class="notice blue platform-scope">${t('Это исследовательская версия: задания и разбор доступны, но результат ещё не переводится в подтверждённый CEFR-уровень. Оплата за точное определение уровня не подключена.','This is a pilot version: tasks and feedback are available, but scores are not yet converted into a validated CEFR level. Payment for precise level assessment is unavailable.')}</div>`;
function keepRecovery(reason='another-tab-changed-saved-progress'){
 if(!session)return;
 recoveryRaw=JSON.stringify({...exportSession(session,bankItems),recovery:{reason,savedAt:new Date().toISOString()}},null,2);
 try{sessionStorage.setItem(RECOVERY_KEY,recoveryRaw);}catch{/* The in-memory copy remains downloadable. */}
}
function markConflict(){if(!writeConflict){writeConflict=true;keepRecovery();}guardRefresh();}
function canEdit(){
 if(writeConflict){guardRefresh();currentNotice(t('Загрузите сохранённую версию через предупреждение. Ваша копия доступна для скачивания.','Use the warning to load the saved version. Your tab copy is available to download.'));return false;}
 return true;
}
function unavailableStorage(){storageOK=false;guardRefresh();currentNotice(t('Не удалось безопасно сохранить прогресс. Скачайте резервную копию.','Progress could not be saved safely. Download a backup.'));}
function save(){
 if(!session)return Promise.resolve(false);
 const snapshot=JSON.stringify(session);
 pendingSaves++;
 // Serialize this tab's snapshots, then compare-and-write under an origin-wide
 // Web Lock. A plain localStorage read/set pair is not atomic across tabs.
 saveQueue=saveQueue.then(async()=>{
  if(writeConflict)return false;
  if(!navigator.locks?.request){unavailableStorage();return true;}
  try{return await navigator.locks.request(SESSION_KEY+':write',()=>{
   if(writeConflict)return false;
   const latest=localStorage.getItem(SESSION_KEY);
   if(latest!==savedRaw){markConflict();return false;}
   localStorage.setItem(SESSION_KEY,snapshot);savedRaw=snapshot;storageOK=true;return true;
  });}catch{unavailableStorage();return true;}
 }).finally(()=>{pendingSaves--;});
 return saveQueue;
}
window.addEventListener('storage',event=>{
 if((event.key===SESSION_KEY||event.key===null)&&read(SESSION_KEY)!==savedRaw)markConflict();
});
window.addEventListener('beforeunload',event=>{
 if(session&&(writeConflict||!storageOK||pendingSaves)){if(writeConflict||pendingSaves)keepRecovery(writeConflict?'another-tab-changed-saved-progress':'pending-save-on-unload');event.preventDefault();event.returnValue='';}
});
function download(name,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function textFor(stimulus){return stimulus?.text??stimulus?.passage??stimulus?.context??'';}
function timeLabel(seconds){return `${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}

function setup(){
 const counts=DOMAINS.map(d=>({d,n:bankItems.filter(q=>q.domain===d).length}));
 return shell(t('Понять, что стоит за ответом.','Understand what sits behind an answer.'),t('Один сфокусированный маршрут: 40 заданий на язык, 40 на чтение и 40 на слух. Можно делать паузы и возвращаться.','One focused route: 40 language-use, 40 reading and 40 listening questions. You can pause and return.'),`
 <label class="file-input platform-import-help">${t('Продолжить из сохранённого файла JSON','Resume from a saved JSON file')}<input type="file" id="attempt-import" accept=".json,application/json"></label><div class="platform-setup-grid"><section class="card"><h2>${t('Перед началом','Before you begin')}</h2><form id="platform-setup-form"><label class="field-label" for="learning-goal">${t('Для чего вам английский? Необязательно.','Why are you learning English? Optional.')}</label><textarea id="learning-goal" name="goal" rows="3" maxlength="300" placeholder="${t('Например: увереннее общаться на работе','For example: communicate more confidently at work')}"></textarea><label class="check-line"><input type="checkbox" name="age" required><span>${t('Мне 16 лет или больше.','I am 16 or older.')}</span></label><label class="check-line"><input type="checkbox" name="understand" required><span>${t('Я понимаю, что это образец для практики и пилотирования, а не сертификат уровня.','I understand this is practice and pilot material, not a level certificate.')}</span></label><p class="small muted">${t('Ответы сохраняются только в этом браузере. Имя, телефон и платёж не нужны. Передача файла преподавателю — по вашему выбору.','Responses stay in this browser. No name, phone number or payment is needed. You choose whether to share a response file with a teacher.')}</p><button type="submit" class="button primary">${t('Начать 120 заданий','Start 120 questions')} →</button></form>${session?`<div class="platform-resume"><p>${t('В этом браузере уже есть прохождение. Начало нового заменит его. Сначала сохраните копию.','An attempt already exists in this browser. Starting again replaces it. Save a copy first.')}</p><div class="actions">${link(session.finished?t('Открыть мой разбор','Open my report'):t('Продолжить','Continue'),session.finished?'my-report':'assessment',true)}${button(t('Скачать копию','Download backup'),'export-attempt')}</div></div>`:''}</section><aside class="card platform-guide"><h2>${t('Что входит','What is included')}</h2><div class="bank-count">${bankItems.length}<span>${t('заданий в банке','questions in the bank')}</span></div>${counts.map(({d,n})=>`<div class="platform-count-row"><span>${domainLabel(d)}</span><strong>${n}</strong></div>`).join('')}<p>${t('Восемь вариантов по 120 вопросов. Тексты и записи сохраняются целыми блоками; часть общих заданий помогает будущему сопоставлению вариантов. Их эквивалентность ещё не подтверждена.','Eight 120-question forms keep passage and recording groups intact. Shared tasks support future comparison of forms; their equivalence is not yet established.')}</p><p>${t('После онлайн-части можно добавить две письменные работы и обсудить разговор с преподавателем.','After the online part, you can add two writing tasks and arrange a conversation with a teacher.')}</p><div class="actions">${link(t('Сначала попробовать 30 заданий','Try 30 questions first'),'sample')}${link(t('Посмотреть банк','Explore the bank'),'bank')}</div></aside></div>${warning()}`);
}
function questionHTML(item){
 const selected=session.answers[item.id],context=item.domain==='language'?textFor(sources.get(item.stimulusId)):'';
 return `<section class="platform-question" data-question-id="${esc(item.id)}">${context?`<div class="context" lang="en">${esc(context)}</div>`:''}<fieldset><legend lang="en">${esc(item.prompt)}</legend><div class="options">${item.choices.map((choice,index)=>`<label class="option"><input type="radio" name="p-${esc(item.id)}" data-p-question="${esc(item.id)}" value="${index}" ${selected===index?'checked':''}><span lang="en">${esc(choice)}</span></label>`).join('')}<label class="option skip"><input type="radio" name="p-${esc(item.id)}" data-p-question="${esc(item.id)}" value="-1" ${selected===null?'checked':''}><span>${t('Пока не знаю','I’m not sure')}</span></label></div></fieldset>${selected==='unavailable'?`<p class="notice">${t('Отмечена проблема со звуком.','Marked as an audio problem.')}</p>`:''}</section>`;
}
function assessment(){
 if(!session)return shell(t('Начните с короткой подготовки.','Start with a short introduction.'),'',link(t('К началу','Get started'),'assessment-setup',true));
 if(session.finished)return personalReport();
 const block=session.blocks[session.position],questions=block.itemIds.map(id=>byId.get(id)),source=sources.get(block.stimulusId),answered=Object.keys(session.answers).length;
 let stimulus='';
 if(block.domain==='reading')stimulus=`<aside class="platform-passage"><div class="eyebrow">${t('Текст к пяти вопросам','Text for five questions')}</div><h2 lang="en">${esc(source?.title||t('Прочитайте текст','Read the text'))}</h2><div lang="en" class="passage-copy">${esc(textFor(source))}</div></aside>`;
 if(block.domain==='listening')stimulus=`<aside class="platform-audio">${listeningPlayerHTML(source,questions,lang).replace('data-action="audio-unavailable"','data-p-action="audio-unavailable"')}<label class="check-line"><input type="checkbox" data-p-familiar ${session.audioExposure[block.stimulusId]?.familiar?'checked':''}><span>${t('Я уже слышал(а) эту запись раньше.','I have heard this recording before.')}</span></label><p class="small muted">${t('Знакомая запись остаётся полезной для практики, но её ответы нельзя считать новой проверкой навыка.','A familiar recording can still help with practice, but its responses cannot count as fresh assessment evidence.')}</p></aside>`;
 return `<main id="main" class="wrap page platform-page">${storageWarning()}<div class="progress-head"><span>${domainLabel(block.domain)} · ${t('Блок','Block')} ${session.position+1} / ${session.blocks.length}</span><span class="platform-progress-count">${answered} /120</span></div><div class="progress" role="progressbar" aria-label="${t('Ответы','Responses')}" aria-valuemin="0" aria-valuemax="120" aria-valuenow="${answered}"><span style="width:${answered/120*100}%"></span></div><div class="platform-test-heading"><h1>${domainLabel(block.domain)}</h1><p class="small muted">${t('Сначала прочитайте все вопросы. Ответы сохраняются при выборе. Ключи будут в разборе после завершения.','Read all the questions first. Selections save automatically. Answer keys appear in your report after completion.')}</p></div><div class="platform-block ${stimulus?'with-stimulus':''}">${stimulus}<form id="platform-answer-form">${questions.map(questionHTML).join('')}<p id="platform-answer-status" role="status" class="small muted"></p><div class="question-actions">${button('← '+t('Назад','Back'),'back',false,session.position===0?'disabled':'')}<button type="submit" class="button primary">${t('Сохранить и продолжить','Save and continue')} →</button></div></form></div><div class="platform-session-tools">${link(t('Сохранить и выйти','Save and leave'),'home')}${button(t('Скачать резервную копию','Download backup'),'export-attempt')}<span class="small muted">${esc(session.formId)} · ${t('Уровень не выводится из текущего счёта','No level is inferred from the current count')}</span></div></main>`;
}
function reviewHTML(item,response,showResponse=true){
 const source=sources.get(item.stimulusId),audio=typeof source?.audio==='string'?source.audio:source?.audio?.src;
 return `<details class="review-item platform-review" data-item-id="${esc(item.id)}"><summary><span class="tag soft">${domainLabel(item.domain)}</span> <span lang="en">${esc(item.prompt)}</span></summary><div class="review-body">${item.domain==='listening'?`<p class="small muted">${esc(source.sourceLabel||'User-supplied Cambridge recording')}</p><audio controls preload="none" src="${esc(audio)}" aria-label="${esc(source.title)}"></audio>`:`<div class="context" lang="en">${esc(textFor(source))}</div>`}${showResponse?`<p><strong>${t('Ваш ответ','Your response')}:</strong> ${response==='unavailable'?t('Не оценивалось: проблема со звуком','Not assessed: audio problem'):response===null?t('Пока не знаю','I’m not sure'):esc(item.choices[response])}</p>`:''}<ol type="A" class="review-choices" lang="en">${item.choices.map((choice,i)=>`<li class="${i===item.correctIndex?'correct':''}">${esc(choice)} ${i===item.correctIndex?'✓':''}</li>`).join('')}</ol><h3>${t('Почему этот ответ','Why this answer')}</h3><p>${esc(local(item.explanation))}</p><p class="audio-evidence"><strong>${t('Основание','Evidence')}:</strong> <span lang="en">${esc(item.answerEvidence)}</span></p>${item.domain==='listening'&&item.evidenceTiming?button('▶ '+t('Послушать фрагмент','Listen to this part')+' · ~'+timeLabel(item.evidenceTiming.startSeconds),'evidence',false,`data-start="${Math.max(0,item.evidenceTiming.startSeconds-1)}"`):''}<h3>${t('Почему другие варианты меняют смысл','Why the alternatives change the meaning')}</h3>${(item.distractorRationales||[]).map(r=>`<p><strong>${String.fromCharCode(65+r.choiceIndex)}.</strong> ${esc(local(r))}</p>`).join('')}<p class="small muted">${esc(local(item.construct))}<br>${esc(item.id)} · ${t('Сложность не калибрована','Difficulty is uncalibrated')}</p></div></details>`;
}
function reportBody(){
 const result=summarizeSession(session,bankItems),questions=session.blocks.flatMap(b=>b.itemIds).map(id=>byId.get(id));
 const selectedSkills=result.skills.filter(s=>s.enoughEvidence&&skillLabels[s.tag]);
 const priorities=result.gaps.filter(s=>skillLabels[s.tag]);
 const patterns=(rows,empty)=>rows.length?rows.map(row=>`<article class="priority"><h3>${esc(labelFor(row.tag,lang))}</h3><p>${domainLabel(row.domain)} · ${row.correct}/${row.total} ${t('ответов подтверждены ключом в','responses match the key across')} ${row.stimulusIds.length} ${t('разных контекстах','different contexts')}.</p><p>${esc(practiceFor(row.domain,row.tag,lang))}</p></article>`).join(''):`<p>${empty}</p>`;
 return `<div class="platform-report-meta"><span class="tag">${esc(session.formId)}</span><span class="small muted">${esc(session.id)}</span></div>${session.goal?`<p><strong>${t('Ваша цель','Your goal')}:</strong> ${esc(session.goal)}</p>`:''}<div class="notice blue">${t('Этот разбор основан на ваших ответах. Он показывает наблюдаемые сильные стороны и трудности, но пока не устанавливает CEFR-уровень или «начало/середину/конец» уровня.','This report is based on your responses. It shows observed strengths and difficulties, but does not yet establish a CEFR level or a beginning/middle/end sublevel.')}</div><div class="grid-3 platform-result-cards">${result.domainStats.map(row=>`<article class="card"><h3>${domainLabel(row.domain)}</h3><div class="result-count">${row.observed?`${row.correct}<span> / ${row.observed}</span>`:t('Не оценивалось','Not assessed')}</div><p>${t('верных ответов в этом варианте','correct responses on this form')}</p><p>${t('Неверно','Incorrect')}: ${row.incorrect} · ${t('Не знаю','Unsure')}: ${row.unsure}</p>${row.unavailable?`<p>${t('Исключено из-за звука','Excluded due to audio')}: ${row.unavailable}</p>`:''}</article>`).join('')}</div>${result.familiarClips?`<div class="notice">${t('Ранее знакомых записей','Previously familiar recordings')}: ${result.familiarClips}. ${t('Эти ответы пригодны для практики; в пилотном анализе они исключаются из новой информации о слушании.','These responses support practice; pilot analysis excludes them as fresh listening evidence.')}</div>`:''}<section class="report-section"><h2>${t('На что можно опереться','What you can build on')}</h2>${patterns(result.strengths.filter(s=>skillLabels[s.tag]),t('Пока недостаточно повторяющихся свидетельств для устойчивого вывода. Посмотрите отдельные успешные ответы ниже.','There is not enough repeated evidence for a stable pattern. Review your individual successful responses below.'))}<p class="small muted">${t('Здесь показываются только признаки с минимум тремя ответами из двух разных контекстов. Это правило описания, а не доказанная точность измерения.','Patterns require at least three responses across two contexts. This is a reporting rule, not an established measurement-accuracy threshold.')}</p></section><section class="report-section"><h2>${t('Полезные направления практики','Useful practice priorities')}</h2>${patterns(priorities,t('Начните с разбора отдельных пропусков и неверных ответов. Если их нет, используйте незнакомые задания и разговор с преподавателем для следующей проверки.','Start with individual unsure or incorrect responses. If there are none, use unfamiliar tasks and a teacher conversation for further evidence.'))}</section><section class="report-section"><h2>${t('Карта наблюдений','Evidence map')}</h2><div class="table-scroll"><table class="skill-table"><thead><tr><th>${t('Навык','Skill')}</th><th>${t('Верно','Correct')}</th><th>${t('Контексты','Contexts')}</th></tr></thead><tbody>${selectedSkills.map(row=>`<tr><td>${esc(labelFor(row.tag,lang))}<br><span class="small muted">${domainLabel(row.domain)}</span></td><td>${row.correct}/${row.total}</td><td>${row.stimulusIds.length}</td></tr>`).join('')}</tbody></table></div></section><section class="report-section"><h2>${t('План на четыре недели','A four-week practice plan')}</h2>${[1,2,3,4].map((week,index)=>{const focus=priorities[index%Math.max(priorities.length,1)],plan=weekPlan(week,focus,lang);return `<article class="week"><div class="eyebrow">${t('Неделя','Week')} ${week}</div><h3>${esc(plan.title)}</h3><p>${esc(plan.body)}</p><p class="small muted">${t('Три занятия по 20–30 минут; увеличьте время, если задания пока трудны. Проверяйте новую ситуацию, а не запоминание ключа.','Use three 20–30 minute sessions; allow more time if needed. Check a new situation rather than recall of the answer key.')}</p></article>`;}).join('')}</section><section class="report-section"><h2>${t('Письмо и разговор дополняют картину','Writing and speaking complete the picture')}</h2><p>${t('Ответы с выбором варианта не показывают полностью, как вы самостоятельно формулируете мысли. Добавьте письменные работы и живой разговор. Без них общего вывода о владении языком нет.','Multiple-choice responses cannot fully show how you formulate your own ideas. Add independent writing and a live conversation. Without them, there is no overall proficiency conclusion.')}</p>${Object.entries(session.writing).map(([id,text])=>`<details><summary>${esc(id)} · ${text.trim().split(/\s+/).filter(Boolean).length} ${t('слов','words')}</summary><blockquote class="quote" lang="en">${esc(text)}</blockquote><p class="small muted">${t('Ожидает оценки преподавателя.','Awaiting teacher assessment.')}</p></details>`).join('')}<div class="actions no-print">${link(t('Добавить две работы','Add two writing tasks'),'writing',true)}<a class="button" href="https://wa.me/77085501378?text=${encodeURIComponent(t('Здравствуйте! Хочу обсудить мой разбор английского и разговор с преподавателем.','Hello! I would like to discuss my English report and a speaking assessment.'))}" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></div></section><section class="report-section platform-answer-appendix"><h2>${t('Каждый ответ можно проверить','Every response is open to review')}</h2><p class="small muted">${t('Ключи открыты для практики. Поэтому этот банк нельзя использовать как защищённый экзамен.','Answer keys are open for practice. This bank is therefore not a secure examination.')}</p>${questions.map(q=>reviewHTML(q,session.answers[q.id])).join('')}</section>`;
}
function personalReport(){if(!session?.finished)return shell(t('Сначала завершите онлайн-часть.','Complete the online tasks first.'),'',link(t('Продолжить','Continue'),'assessment',true));return shell(t('Ваш английский — в конкретных ответах.','Your English, through your own responses.'),t('Личный разбор этого прохождения и следующие шаги.','A personal review of this attempt and your next steps.'),`<div class="report-toolbar no-print">${button(t('Печать обзора / PDF','Print summary / PDF'),'print',true)}${button(t('Скачать отчёт HTML','Download HTML report'),'report-html')}${button(t('Ответы для преподавателя','Responses for a teacher'),'export-attempt')}</div>${reportBody()}`);}
function writing(){
 if(!session)return setup();const track=writingTasks[writingTrack];
 return shell(t('Покажите свой собственный английский.','Show your own English.'),t('Две самостоятельные работы для преподавателя. Выберите посильный набор; его название не является результатом теста.','Two independent pieces for a teacher. Choose a manageable set; its label is not a test result.'),`<div class="filters">${Object.entries(writingTasks).map(([key,value])=>button(value.label[lang==='ru'?0:1],'writing-track',false,`data-track="${key}" aria-pressed="${writingTrack===key}"`)).join('')}</div><p class="notice blue">${t('Пишите без переводчика и готового текста. Можно сохранить черновик. Автоматическая оценка уровня по этим работам не производится.','Write without a translator or prepared text. You can save a draft. These responses do not receive an automated level score.')}</p>${track.tasks.map(task=>`<section class="card platform-writing"><h2 lang="en">${esc(task.prompt)}</h2><label class="field-label" for="${task.id}">${task.guidance[lang==='ru'?0:1]}</label><textarea id="${task.id}" data-p-writing="${task.id}" lang="en" rows="12" maxlength="10000">${esc(session.writing[task.id]||'')}</textarea><p class="small muted" data-word-count="${task.id}"></p></section>`).join('')}<div class="actions">${button(t('Скачать работы и ответы','Download writing and responses'),'export-attempt',true)}${link(t('Вернуться к разбору','Return to my report'),'my-report')}</div>`);
}
function catalogue(){
 const filtered=bankItems.filter(q=>(domainFilter==='all'||q.domain===domainFilter)&&(levelFilter==='all'||q.targetLevel===levelFilter)&&(!search||`${q.prompt} ${q.topic||''} ${q.id}`.toLowerCase().includes(search.toLowerCase()))),pages=Math.max(1,Math.ceil(filtered.length/20));page=Math.min(page,pages-1);
 return shell(`${bankItems.length} ${t('заданий. Смысл каждого открыт.','questions. A purpose for every one.')}`,t('Каталог для практики и проверки содержания. Цели авторов A1–C1 не являются измеренными уровнями сложности; слушанию уровень не присвоен.','A catalogue for practice and content review. A1–C1 authoring targets are not measured difficulty levels; listening tasks have no assigned level.'),`<form id="bank-filter-form" class="bank-controls"><label>${t('Навык','Skill')}<select name="domain">${['all',...DOMAINS].map(d=>`<option value="${d}" ${domainFilter===d?'selected':''}>${d==='all'?t('Все','All'):domainLabel(d)}</option>`).join('')}</select></label><label>${t('Цель автора','Authoring target')}<select name="level">${['all',...LEVELS].map(l=>`<option value="${l}" ${levelFilter===l?'selected':''}>${l==='all'?t('Все','All'):l}</option>`).join('')}</select></label><label>${t('Поиск','Search')}<input name="search" value="${esc(search)}" maxlength="100"></label><button class="button" type="submit">${t('Показать','Show')}</button></form><p class="small muted">${filtered.length} ${t('заданий найдено','questions found')} · ${page+1}/${pages}</p><div class="review-list">${filtered.slice(page*20,page*20+20).map(q=>reviewHTML(q,null,false)).join('')}</div><div class="actions">${button('← '+t('Назад','Previous'),'bank-prev',false,page===0?'disabled':'')}${button(t('Далее','Next')+' →','bank-next',false,page===pages-1?'disabled':'')}</div>`);
}

// Staff-facing local tools. No files are uploaded to a server.
function teacher(){return shell(t('Рабочее место преподавателя.','Teacher review workspace.'),t('Импортируйте файл прохождения. Проверьте самостоятельные ответы и сохраните отдельный черновик обратной связи.','Import an attempt file. Review independent responses and save a separate feedback draft.'),`<div class="notice blue">${t('Все данные остаются в этой вкладке. Это локальный инструмент без подтверждения личности проверяющего; он не создаёт сертификат.','Data stays in this tab. This local tool does not authenticate the reviewer or issue a certificate.')}</div><label class="file-input">${t('Файл ответов JSON','Response JSON file')}<input type="file" id="teacher-import" accept=".json,application/json"></label>${teacherAttempt?`<section class="card"><h2>${esc(teacherAttempt.id)}</h2><p>${esc(teacherAttempt.goal)}</p><div class="grid-3">${summarizeSession(teacherAttempt,bankItems).domainStats.map(r=>`<p><strong>${domainLabel(r.domain)}</strong><br>${r.correct}/${r.observed} · ${t('не знаю','unsure')}: ${r.unsure}</p>`).join('')}</div><h3>${t('Самостоятельное письмо','Independent writing')}</h3>${Object.entries(teacherAttempt.writing).length?Object.entries(teacherAttempt.writing).map(([id,text])=>`<h4>${esc(id)}</h4><blockquote class="quote" lang="en">${esc(text)}</blockquote>`).join(''):`<p>${t('Работы не приложены.','No writing responses were included.')}</p>`}<form id="teacher-feedback-form"><label class="field-label">${t('Проверяющий','Reviewer')}<input name="reviewer" required maxlength="100"></label>${['writing','speaking'].map(skill=>`<fieldset class="teacher-criterion"><legend>${domainLabel(skill)}</legend><p class="small muted">${skill==='writing'?t('Отметьте выполнение задачи, связность, диапазон и точность. Приведите фразы из работы.','Consider task fulfilment, coherence, range and accuracy. Quote evidence from the writing.'):t('После живого разговора отметьте взаимодействие, беглость, понятность, диапазон и точность. Укажите конкретные наблюдения.','After a live conversation, consider interaction, fluency, intelligibility, range and accuracy. Record specific observations.')}</p><label>${t('Предварительное суждение преподавателя','Provisional teacher judgement')}<select name="${skill}-level"><option value="unassessed">${t('Недостаточно данных','Insufficient evidence')}</option>${LEVELS.map(l=>`<option>${l}</option>`).join('')}</select></label><label class="field-label">${t('Наблюдения и основания','Observations and supporting evidence')}<textarea name="${skill}-evidence" rows="4" maxlength="4000"></textarea></label><label class="field-label">${t('Что проверить дополнительно','What to check next')}<textarea name="${skill}-next" rows="2" maxlength="2000"></textarea></label></fieldset>`).join('')}<button type="submit" class="button primary">${t('Скачать черновик обратной связи','Download feedback draft')}</button></form></section>`:''}<section class="card platform-staff-notes"><h2>${t('Для независимой проверки','For independent review')}</h2><p>${t('В исследовании второй проверяющий сначала оценивает работу самостоятельно, без первого заключения и автоматических баллов. Сравните расхождения, затем проведите согласование. Этот интерфейс предназначен для обратной связи; слепое распределение и учёт оценок потребуют отдельного протокола.','In a study, a second reviewer should first rate independently without seeing the first judgement or automated scores. Compare differences, then adjudicate. This interface supports feedback; blinded allocation and rating records need a separate protocol.')}</p></section>`);}
function pilot(){
 const data=pilotResult;
 return shell(t('Проверка на данных учеников.','Inspection of learner evidence.'),t('Здесь нет выдуманных результатов. Статистика появляется только после импорта реальных файлов прохождения.','There are no invented results here. Statistics appear only after actual attempt files are imported.'),`<label class="file-input">${t('Файлы прохождений JSON; можно выбрать несколько','Attempt JSON files; multiple selection supported')}<input type="file" id="pilot-import" accept=".json,application/json" multiple></label><div class="actions">${button(t('Очистить данные вкладки','Clear tab data'),'pilot-clear')}${data?button(t('Скачать анализ','Download inspection'),'pilot-export'):''}</div>${data?`<div class="grid-3 platform-result-cards"><article class="card"><strong class="bank-count">${data.accepted}</strong><p>${t('принято уникальных прохождений','unique attempts accepted')}</p></article><article class="card"><strong class="bank-count">${data.completed}</strong><p>${t('завершено; незавершённых','completed; incomplete')}: ${data.incomplete}</p></article><article class="card"><strong class="bank-count">${data.rejected.length}</strong><p>${t('отклонено: повторы или несовместимые данные','rejected: duplicates or incompatible data')}</p></article></div><h2>${t('Сопоставимые варианты','Comparable forms')}</h2><p class="muted">${t('Результаты разных вариантов не смешиваются. Коэффициенты показываются только при 30 полных наблюдениях на одинаковый набор заданий; это технический порог вывода, а не достаточный размер исследования.','Different forms are not pooled. Coefficients require 30 complete observations on the same tasks; this is a reporting threshold, not a sufficient study size.')}</p><div class="table-scroll"><table class="skill-table"><thead><tr><th>${t('Навык / вариант','Skill / form')}</th><th>N</th><th>${t('Среднее верно','Mean correct')}</th><th>α ${t('по заданиям','items')}</th><th>α ${t('по стимулам','clusters')}</th></tr></thead><tbody>${data.forms.map(f=>`<tr><td>${domainLabel(f.domain)} · ${f.formId}</td><td>${f.n}</td><td>${f.meanCorrect.toFixed(1)}/40</td><td>${f.itemAlpha===null?'—':f.itemAlpha.toFixed(3)}</td><td>${f.stimulusClusterAlpha===null?'—':f.stimulusClusterAlpha.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><h2>${t('Покрытие банка','Bank exposure')}</h2><p>${data.items.filter(q=>q.n>0).length}/${bankItems.length} ${t('заданий имеют хотя бы один ответ;','items have at least one response;')} ${data.items.filter(q=>q.n>=30).length} ${t('имеют 30 наблюдений.','have 30 observations.')}</p><p>${t('В скачиваемом файле для каждого задания есть частота верных ответов, интервал Уилсона, выбор отвлекающих вариантов и исключения по звуку/знакомству. Это описание выборки, а не калибровка CEFR.','The download includes item proportions, Wilson intervals, distractor choices and audio/familiarity exclusions. These describe the sample; they are not CEFR calibration.')}</p>`:`<section class="card empty-state"><div class="bank-count">0</div><h2>${t('Данных учеников пока нет','No learner data yet')}</h2><p>${t('Надёжность, точность классификации и границы уровней не установлены. Технически исправный сайт не заменяет исследование.','Reliability, classification accuracy and level cutoffs are not established. Working software does not replace a study.')}</p></section>`}<section class="report-section"><h2>${t('Что нужно для обоснованного уровня','What a defensible level requires')}</h2><ol class="validation-steps"><li>${t('Согласовать назначение теста, выборку 16+, охват навыков и риски ошибочного распределения.','Define intended use, the 16+ population, skill coverage and consequences of misplacement.')}</li><li>${t('Провести независимую экспертную проверку и интервью с учениками о том, как они решают задания.','Run independent expert reviews and cognitive interviews about how learners answer.')}</li><li>${t('Пилотировать задания на подходящей выборке с достаточным числом ответов на каждый вопрос и общей связью вариантов.','Pilot with an appropriate sample, sufficient responses per item and links between forms.')}</li><li>${t('Проверить трудность, различающую способность, отвлекающие варианты, зависимость вопросов и справедливость для разных групп.','Examine difficulty, discrimination, distractors, item dependence and fairness across groups.')}</li><li>${t('Установить CEFR-границы с обученными экспертами и проверить их на отдельной выборке с независимой оценкой.','Set CEFR boundaries with trained experts and test them on a separate sample with independent reference assessments.')}</li><li>${t('Оценить согласие двух проверяющих речи и письма, устойчивость при повторе и неопределённость пограничных результатов.','Evaluate speaking/writing rater agreement, retest stability and uncertainty near boundaries.')}</li><li>${t('Опубликовать технический отчёт, условия пересмотра результата и ограничения. Начало/середина/конец уровня требуют отдельного обоснования.','Publish a technical report, review procedures and limits. Beginning/middle/end sublevels require their own evidence.')}</li></ol><p class="small muted">${t('Коэффициент α сам по себе не доказывает точность уровня. Неизвестное качество остаётся неизвестным, сколько бы вопросов ни было в банке.','Alpha alone does not establish level accuracy. Unknown quality remains unknown regardless of bank size.')}</p></section>`);
}
export function renderPlatform(route,language){lang=language;switch(route){case'assessment-setup':return setup();case'assessment':return assessment();case'my-report':return personalReport();case'writing':return writing();case'bank':return catalogue();case'teacher-review':return teacher();case'pilot-lab':return pilot();default:return null;}}

export function mountPlatform(root,{language,onRender,onNotice}){
 lang=language;currentNotice=onNotice;let audioCleanup=null;
 const refreshGuard=()=>{
  const main=root.matches('main')?root:root.querySelector('main');if(!main)return;
  main.querySelector('.platform-conflict-warning')?.remove();
  if(!storageOK&&!main.querySelector('.platform-storage-warning'))main.insertAdjacentHTML('afterbegin',`<div class="notice platform-storage-warning">${t('Безопасное сохранение в браузере недоступно. Скачайте ответы перед закрытием вкладки.','Safe browser saving is unavailable. Download your responses before closing this tab.')}</div>`);
  if(writeConflict||recoveryRaw)main.insertAdjacentHTML('afterbegin',conflictWarning());
  if(writeConflict){
   for(const node of main.querySelectorAll('#platform-setup-form input,#platform-setup-form textarea,#platform-setup-form button,#platform-answer-form input,#platform-answer-form button,[data-p-writing],[data-p-familiar],#attempt-import,[data-p-action="back"],[data-p-action="audio-unavailable"]'))node.disabled=true;
   for(const audio of main.querySelectorAll('audio'))audio.pause();
  }
 };
 guardRefresh=refreshGuard;
 const route=()=>location.hash.slice(1).split('?')[0],go=destination=>{if(route()===destination)onRender();else location.hash=destination;};
 const submitAvailability=()=>{const form=root.querySelector('#platform-answer-form');if(!form||!session)return;if(writeConflict){form.querySelector('button[type="submit"]').disabled=true;return;}const block=session.blocks[session.position],complete=block.itemIds.every(id=>Object.hasOwn(session.answers,id)),hasChoice=block.itemIds.some(id=>Number.isInteger(session.answers[id])),audioOK=block.domain!=='listening'||!hasChoice||listeningAnswerAvailable();form.querySelector('button[type="submit"]').disabled=!complete||!audioOK;root.querySelector('#platform-answer-status').textContent=!complete?t('Отметьте ответ или «Пока не знаю» для каждого вопроса.','Choose an answer or “I’m not sure” for every question.'):!audioOK?t('Прослушайте запись перед отправкой ответов. При проблеме со звуком используйте пропуск.','Play the recording before submitting answers. Use the audio-problem option if needed.'):t('Ответы готовы к сохранению.','Responses are ready to save.');};
 if(route()==='assessment'&&session&&!session.finished&&session.blocks[session.position].domain==='listening'){
  const block=session.blocks[session.position];audioCleanup=mountListeningPlayer(root.querySelector('.listening-player'),sources.get(block.stimulusId),lang,submitAvailability);
  root.querySelector('#task-audio').addEventListener('play',async event=>{if(!canEdit()){event.target.pause();return;}const previous=session.audioExposure[block.stimulusId]||{};session.audioExposure[block.stimulusId]={...previous,starts:(previous.starts||0)+1};await save();});
 }
 submitAvailability();
 const words=()=>{for(const node of root.querySelectorAll('[data-p-writing]')){const output=root.querySelector(`[data-word-count="${node.dataset.pWriting}"]`);output.textContent=`${node.value.trim().split(/\s+/).filter(Boolean).length} ${t('слов · черновик сохраняется','words · draft saves automatically')}`;}};words();
 const change=async event=>{
  const node=event.target;
  if(node.dataset.pQuestion){if(!canEdit())return;session=answerQuestion(session,node.dataset.pQuestion,Number(node.value)===-1?null:Number(node.value),bankItems);if(!await save())return;submitAvailability();const count=root.querySelector('.platform-progress-count');if(count)count.textContent=`${Object.keys(session.answers).length} /120`;const bar=root.querySelector('.progress');if(bar){bar.setAttribute('aria-valuenow',Object.keys(session.answers).length);bar.firstElementChild.style.width=`${Object.keys(session.answers).length/120*100}%`;}return;}
  if(node.matches('[data-p-familiar]')){if(!canEdit())return;const id=session.blocks[session.position].stimulusId;session.audioExposure[id]={...(session.audioExposure[id]||{}),familiar:node.checked};await save();return;}
  if(node.id==='attempt-import'||node.id==='teacher-import'||node.id==='pilot-import'){
   try{
    const files=[...node.files];if(files.length>1000)throw new Error(t('Не более 1000 файлов за раз.','Use at most 1000 files at a time.'));
    const loaded=[];for(const file of files){if(file.size>5*1024*1024)throw new Error(t('Файл слишком большой.','File is too large.'));const data=JSON.parse(await file.text());loaded.push(...(Array.isArray(data)?data:[data]));}
    if(node.id==='attempt-import'){if(!canEdit())return;const imported=loadSession(JSON.stringify(loaded[0]?.session),bankItems,BANK_VERSION);if(!imported)throw new Error(t('Несовместимый или повреждённый файл.','Incompatible or damaged file.'));session=imported;if(!await save())return;clearListeningPositions();go(session.finished?'my-report':'assessment');return;}
    if(node.id==='teacher-import'){const imported=loadSession(JSON.stringify(loaded[0]?.session),bankItems,BANK_VERSION);if(!imported)throw new Error(t('Несовместимый или повреждённый файл прохождения.','Incompatible or damaged attempt file.'));teacherAttempt=imported;teacherDraft=null;}
    else{const candidate=[...pilotEntries,...loaded],result=analyzePilot(candidate,bankItems,BANK_VERSION);pilotEntries=candidate;pilotResult=result;}
    onRender();
   }catch(error){onNotice(t('Не удалось импортировать: ','Import failed: ')+error.message);}
  }
 };
 const input=async event=>{const node=event.target;if(node.dataset.pWriting){if(!canEdit())return;session.writing[node.dataset.pWriting]=node.value.slice(0,10000);await save();words();}};
 const submit=async event=>{
  const form=event.target;
  if(!['platform-setup-form','platform-answer-form','bank-filter-form','teacher-feedback-form'].includes(form.id))return;event.preventDefault();
  if(form.id==='platform-setup-form'){
   if(!canEdit()||!form.reportValidity())return;try{session=createSession({items:bankItems,bankVersion:BANK_VERSION,seed:crypto.getRandomValues(new Uint32Array(1))[0]%FORM_COUNT+1,id:crypto.randomUUID(),goal:new FormData(form).get('goal')});if(!await save())return;clearListeningPositions();go('assessment');}catch(error){onNotice(t('Подготовка банка ещё не завершена: ','Bank preparation is not complete: ')+error.message);}return;
  }
  if(form.id==='platform-answer-form'){
   if(!canEdit())return;
   const block=session.blocks[session.position];if(block.domain==='listening'&&block.itemIds.some(id=>Number.isInteger(session.answers[id]))&&!listeningAnswerAvailable()){submitAvailability();return;}
   try{session=completeBlock(session);if(!await save())return;if(session.finished)go('my-report');else onRender();}catch(error){onNotice(error.message);}return;
  }
  if(form.id==='bank-filter-form'){const data=new FormData(form);domainFilter=data.get('domain');levelFilter=data.get('level');search=String(data.get('search')).slice(0,100);page=0;onRender();return;}
  if(form.id==='teacher-feedback-form'){
   if(!form.reportValidity())return;const data=new FormData(form),ratings={};
   for(const skill of ['writing','speaking']){const level=data.get(`${skill}-level`),evidence=String(data.get(`${skill}-evidence`)).trim();if(level!=='unassessed'&&evidence.length<40){onNotice(t('Перед суждением об уровне укажите конкретные основания: минимум 40 символов.','Provide specific supporting evidence before a level judgement: at least 40 characters.'));return;}ratings[skill]={provisionalLevel:level==='unassessed'?null:level,evidence,nextCheck:String(data.get(`${skill}-next`))};}
   teacherDraft={type:'nurkanat-teacher-feedback-draft',bankVersion:BANK_VERSION,attemptId:teacherAttempt.id,reviewer:String(data.get('reviewer')).trim(),createdAt:new Date().toISOString(),authenticated:false,ratings,notice:'Local reviewer draft; not independently authenticated or a validated certificate.'};download(`teacher-feedback-${teacherAttempt.id}.json`,JSON.stringify(teacherDraft,null,2));
  }
 };
 const click=async event=>{
  const element=event.target.closest('[data-p-action]');if(!element)return;
  switch(element.dataset.pAction){
   case'back':if(canEdit()&&session.position>0){session={...session,position:session.position-1};if(await save())onRender();}break;
   case'conflict-backup':if(recoveryRaw)download('english-tab-recovery.json',recoveryRaw);else if(session)download(`english-attempt-${session.id}.json`,JSON.stringify(exportSession(session,bankItems),null,2));break;
   case'conflict-dismiss':if(!writeConflict){recoveryRaw=null;try{sessionStorage.removeItem(RECOVERY_KEY);}catch{}refreshGuard();}break;
   case'conflict-reload':{
    await saveQueue;
    if(recoveryRaw)download('english-tab-recovery.json',recoveryRaw);
    else if(session)download(`english-attempt-${session.id}.json`,JSON.stringify(exportSession(session,bankItems),null,2));
    let latest;try{latest=localStorage.getItem(SESSION_KEY);}catch{unavailableStorage();break;}
    savedRaw=latest;session=loadSession(latest,bankItems,BANK_VERSION);writeConflict=false;storageOK=true;clearListeningPositions();
    go(session?(session.finished?'my-report':'assessment'):'assessment-setup');break;
   }
   case'export-attempt':if(session)download(`english-attempt-${session.id}.json`,JSON.stringify(exportSession(session,bankItems),null,2));break;
   case'audio-unavailable':if(canEdit()&&session&&!session.finished){for(const id of session.blocks[session.position].itemIds)session=answerQuestion(session,id,'unavailable',bankItems);session=completeBlock(session);if(await save())session.finished?go('my-report'):onRender();}break;
   case'writing-track':writingTrack=element.dataset.track;onRender();break;
   case'bank-prev':page=Math.max(0,page-1);onRender();break;
   case'bank-next':page++;onRender();break;
   case'print':window.print();break;
   case'report-html':try{const css=(await Promise.all(['benchmark.css','platform.css'].map(async url=>{const response=await fetch(url);if(!response.ok)throw new Error('style');return response.text();}))).join('\n');download(`english-report-${session.id}-${lang}.html`,`<!doctype html><html lang="${lang}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${t('Мой разбор английского','My English report')}</title><style>${css}.no-print,audio,[data-p-action]{display:none!important}</style><body><main class="wrap page platform-page"><h1>${t('Мой разбор английского','My English report')}</h1>${reportBody()}</main></body></html>`,'text/html;charset=utf-8');}catch{onNotice(t('Не удалось скачать отчёт. Попробуйте печать.','The report could not download. Try printing.'));}break;
   case'evidence':{const audio=element.closest('.review-body')?.querySelector('audio');if(audio){for(const other of root.querySelectorAll('audio'))if(other!==audio)other.pause();try{audio.currentTime=Number(element.dataset.start);await audio.play();}catch{onNotice(t('Запись не загрузилась. Повторите попытку.','Recording did not load. Please retry.'));}}break;}
   case'pilot-clear':pilotEntries=[];pilotResult=null;onRender();break;
   case'pilot-export':if(pilotResult)download('pilot-inspection.json',JSON.stringify(pilotResult,null,2));break;
  }
 };
 root.addEventListener('change',change);root.addEventListener('input',input);root.addEventListener('submit',submit);root.addEventListener('click',click);
 refreshGuard();
 return()=>{if(guardRefresh===refreshGuard)guardRefresh=()=>{};audioCleanup?.();root.removeEventListener('change',change);root.removeEventListener('input',input);root.removeEventListener('submit',submit);root.removeEventListener('click',click);};
}



